function createPgAdapter(){
 const connectionString=process.env.SUPABASE_DB_URL||process.env.DATABASE_URL;
 if(!connectionString) throw new Error('Missing SUPABASE_DB_URL (Supabase PostgreSQL connection string)');
 const pool=new Pool({connectionString,ssl:process.env.PGSSLMODE==='disable'?false:{rejectUnauthorized:false},max:Number(process.env.PG_POOL_MAX||5),options:'-c search_path=nasim'});
 const txContext=new AsyncLocalStorage();
 const query=async(text,values=[])=>{const client=txContext.getStore()||pool;return client.query(text,values)};
 const tablesWithId=new Set('accounting_accounts accounting_periods additional_discount_requests addons audit_logs booking_activity booking_addon_sales booking_adjustments booking_bride_rooms booking_change_requests booking_contractors booking_files booking_operational_addons booking_status_history booking_work_contractors bookings bride_rooms buffet_items buffet_packages cash_journal contractors contractor_payouts customers discount_requests expense_receipts followups halls hall_offers hall_packages inquiries independent_events inventory_alerts inventory_items inventory_movements inventory_movements invitation_cards invitation_checkins inquiry_events journal_entries journal_lines official_holidays operational_addons payments users work_order_history work_order_lines work_orders'.split(/\s+/));
 const placeholders=(raw)=>{let out='',i=0,quote=null;for(let n=0;n<raw.length;n++){const c=raw[n];if(quote){out+=c;if(c===quote){if(raw[n+1]===quote){out+=raw[++n]}else quote=null}if(c==='\\'&&quote&&n+1<raw.length)out+=raw[++n];continue;}if(c==="'"||c==='"'||c==='`'){quote=c;out+=c;continue;}if(c==='?'){out+='$'+(++i);continue;}out+=c;}return out};
 const convertSql=(input,method)=>{const raw=String(input);let sql=placeholders(raw);const ignore=/INSERT\s+OR\s+IGNORE\s+INTO\s+(\w+)/i.exec(raw),replace=/INSERT\s+OR\s+REPLACE\s+INTO\s+(\w+)/i.exec(raw);sql=sql.replace(/INSERT\s+OR\s+IGNORE\s+INTO/ig,'INSERT INTO').replace(/INSERT\s+OR\s+REPLACE\s+INTO/ig,'INSERT INTO');sql=sql.replace(/group_concat\s*\(/ig,'string_agg(').replace(/char\(10\)/ig,'chr(10)').replace(/datetime\('now'\s*,\s*'-1 minute'\)/ig,"(CURRENT_TIMESTAMP - INTERVAL '1 minute')");sql=sql.replace(/printf\('%s × %g',\s*([^,]+),\s*([^)]+)\)/ig,"concat($1, ' × ', $2::text)");sql=sql.replace(/datetime\('now'\)/ig,'CURRENT_TIMESTAMP').replace(/date\('now'\s*,\s*'localtime'\)/ig,'CURRENT_DATE').replace(/date\('now'\)/ig,'CURRENT_DATE').replace(/datetime\(scheduled_at\)/ig,'scheduled_at::timestamp').replace(/date\(scheduled_at\)/ig,'scheduled_at::date');if(ignore)sql+=' ON CONFLICT DO NOTHING';if(replace)sql=sql.replace(/VALUES\s*\(([^)]*)\)\s*$/i,'VALUES($1) ON CONFLICT (package_id,item_id) DO UPDATE SET quantity=EXCLUDED.quantity, quantity_basis=EXCLUDED.quantity_basis');if(method==='run'&&/^\s*INSERT\b/i.test(sql)&&!(/\bRETURNING\b/i.test(sql))&&!/ON CONFLICT\s+DO NOTHING/i.test(sql)){const table=/INSERT\s+INTO\s+(\w+)/i.exec(sql)?.[1];if(table&&tablesWithId.has(table))sql+=' RETURNING id';}return sql;};
 return {prepare(sql){return {get:async(...args)=>{const r=await query(convertSql(sql,'get'),args);return r.rows[0]},all:async(...args)=>{const r=await query(convertSql(sql,'all'),args);return r.rows},run:async(...args)=>{const r=await query(convertSql(sql,'run'),args);return {changes:r.rowCount,lastInsertRowid:r.rows[0]?.id}}}},exec:async(sql)=>query(sql),transaction(fn){return async(...args)=>{const client=await pool.connect();try{return await txContext.run(client,async()=>{await client.query('BEGIN');try{const value=await fn(...args);await client.query('COMMIT');return value}catch(e){await client.query('ROLLBACK');throw e}})}finally{client.release()}}},close:()=>pool.end()};
}
const STORAGE_URL=String(process.env.SUPABASE_URL||'').replace(/\/$/,'');
const STORAGE_KEY=process.env.SUPABASE_SERVICE_ROLE_KEY||process.env.SUPABASE_SECRET_KEY;
const STORAGE_BUCKET=process.env.SUPABASE_STORAGE_BUCKET||'nasim-booking-files';
async function storageRequest(method,objectPath,body,contentType){
 if(!STORAGE_URL||!STORAGE_KEY)throw new Error('Supabase Storage environment variables are not configured');
 const url=STORAGE_URL+'/storage/v1/object/'+encodeURIComponent(STORAGE_BUCKET)+'/'+objectPath.split('/').map(encodeURIComponent).join('/');
 const response=await fetch(url,{method,headers:{apikey:STORAGE_KEY,Authorization:'Bearer '+STORAGE_KEY,...(contentType?{'Content-Type':contentType}:{})},...(body!==undefined?{body}:{} )});
 if(!response.ok)throw new Error('Supabase Storage error '+response.status+': '+(await response.text()).slice(0,300));
 return response;
}

