  const buffetPackages=(await db.prepare("SELECT bp.name, SUM(bb.guest_count) qty FROM booking_buffets bb JOIN buffet_packages bp ON bp.id=bb.buffet_package_id WHERE bb.booking_id=? GROUP BY bp.id,bp.name").all(bookingId));
