function normalizePermissions(value){const out=[...new Set((Array.isArray(value)?value:[]).filter(p=>PERMS.includes(p)))];for(const p of out.filter(x=>x.startsWith('edit_'))){const base=p.slice(5);if(MODULE_PERMS.includes(base)&&!out.includes(base))out.push(base)}return out;}
