app.get('/api/contractor-report',auth,permit('contractor_report'),async (req,res)=>{const rows=(await db.prepare(`SELECT bc.id,bc.booking_id,bc.contractor_id,bc.contractor_name,bc.job_title,bc.hall_name,bc.cost_amount,b.booking_no,b.event_date,b.start_time,b.end_time,b.guest_count,c.full_name customer_name,COALESCE((SELECT SUM(cp.amount) FROM contractor_payouts cp WHERE cp.contractor_id=bc.contractor_id AND (cp.booking_id=bc.booking_id OR cp.booking_id IS NULL)),0) paid_total FROM booking_contractors bc JOIN bookings b ON b.id=bc.booking_id LEFT JOIN customers c ON c.id=b.customer_id ORDER BY b.event_date DESC`).all());res.json({rows,contractors:(await db.prepare(`SELECT c.id,c.full_name,c.job_title,c.hall_id,COALESCE((SELECT SUM(bc.cost_amount) FROM booking_contractors bc WHERE bc.contractor_id=c.id),0) owed,COALESCE((SELECT SUM(cp.amount) FROM contractor_payouts cp WHERE cp.contractor_id=c.id),0) paid FROM contractors c WHERE c.active=1 ORDER BY c.full_name`).all()),halls:(await db.prepare('SELECT id,name FROM halls ORDER BY name').all())})});
app.post('/api/contractor-payouts',auth,permit('cashbox'),async (req,res)=>{if(req.user.role==='admin')return res.status(403).json({error:'الأدمن لا يسجل صرف الخزنة'});const d=req.body||{},amount=Number(d.amount),contractor=(await db.prepare('SELECT * FROM contractors WHERE id=? AND active=1').get(Number(d.contractor_id)));const bookingId=Number(d.booking_id)||null;if(bookingId&&!(await db.prepare('SELECT 1 FROM booking_contractors WHERE booking_id=? AND contractor_id=?').get(bookingId,Number(d.contractor_id))))return res.status(400).json({error:'الحجز المختار غير مسند لهذا المتعهد'});if(!contractor||!Number.isFinite(amount)||amount<=0||!['cash','bank_transfer','instapay'].includes(d.method))return res.status(400).json({error:'راجع المتعهد والمبلغ وطريقة الدفع'});const tx=db.transaction(async ()=>{const next=(await db.prepare('SELECT COALESCE(MAX(id),0)+1 n FROM cash_journal').get()).n;const entry='NS-JV-'+String(next).padStart(8,'0');const j=(await db.prepare(`INSERT INTO cash_journal(entry_no,entry_type,category,amount,method,description,contractor_id,created_by) VALUES(?,'expense','مستحقات متعهد',?,?,?,?,?)`).run(entry,amount,d.method,`صرف مستحقات ${contractor.full_name} — ${contractor.job_title} — ${String(d.notes||'')}`,contractor.id,req.user.id));const pn=(await db.prepare('SELECT COALESCE(MAX(id),0)+1 n FROM contractor_payouts').get()).n;const receipt='NS-CP-'+String(pn).padStart(8,'0');(await db.prepare('INSERT INTO contractor_payouts(receipt_no,contractor_id,amount,method,reference,notes,paid_by,journal_id,booking_id) VALUES(?,?,?,?,?,?,?,?,?)').run(receipt,contractor.id,amount,d.method,String(d.reference||''),String(d.notes||''),req.user.id,j.lastInsertRowid,bookingId));(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'contractor_payout','contractor',contractor.id));return {receipt_no:receipt,entry_no:entry}});try{res.json(await tx())}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/cash-journal',auth,async (req,res)=>{const isAdmin=req.user.role==='admin',scope=String(req.query.scope||'all'),canCashbox=isAdmin||req.user.permissions.includes('cashbox')||req.user.permissions.includes('edit_cashbox'),canExpenses=isAdmin||req.user.permissions.includes('expenses')||req.user.permissions.includes('edit_expenses');if(scope==='expenses'&&!canExpenses)return res.status(403).json({error:'ليس لديك صلاحية عرض المصروفات والمشتريات'});if(scope!=='expenses'&&!canCashbox)return res.status(403).json({error:'ليس لديك صلاحية عرض حركة الخزنة واليومية'});const where=scope==='expenses'?"WHERE j.entry_type='expense'":"";const sql=`SELECT j.*,u.full_name employee,c.full_name contractor,b.booking_no,p.payment_type payment_type,p.receipt_no payment_receipt_no,p.notes payment_notes,p.reference payment_reference,e.id receipt_id,e.receipt_no,e.print_count,e.invoice_image FROM cash_journal j LEFT JOIN users u ON u.id=j.created_by LEFT JOIN contractors c ON c.id=j.contractor_id LEFT JOIN bookings b ON b.id=j.booking_id LEFT JOIN payments p ON p.id=j.payment_id LEFT JOIN expense_receipts e ON e.journal_id=j.id ${where} ORDER BY j.id DESC LIMIT 500`;res.json((await db.prepare(sql).all()))});
app.delete('/api/cash-journal/:id',auth,(req,res,next)=>{if(req.user.role==='admin'||req.user.permissions.includes('delete_cash_journal')||req.user.permissions.includes('delete_all_data'))return next();return res.status(403).json({error:'ليس لديك صلاحية مسح قيود الخزنة'});},async (req,res)=>{try{const row=(await db.prepare('SELECT * FROM cash_journal WHERE id=?').get(req.params.id));if(!row)return res.status(404).json({error:'القيد غير موجود'});if(row.entry_type!=='expense'||row.payment_id||row.contractor_id)return res.status(409).json({error:'لا يمكن مسح هذا القيد مباشرة لأنه مرتبط بتحصيل أو متعهد. يجب تصحيح الحركة من مصدرها للحفاظ على الحسابات.'});const tx=db.transaction(async ()=>{(await db.prepare('DELETE FROM expense_receipts WHERE journal_id=?').run(row.id));(await db.prepare('DELETE FROM cash_journal WHERE id=?').run(row.id));(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'delete','cash_journal',row.id,JSON.stringify({entry_no:row.entry_no,amount:row.amount,category:row.category})));});await tx();res.json({ok:true})}catch(e){res.status(400).json({error:'تعذر مسح القيد؛ قد يكون مرتبطًا ببيانات أخرى.'})}});
app.post('/api/cash-journal/expense',auth,async (req,res)=>{if(req.user.role==='admin')return res.status(403).json({error:'الأدمن لا يسجل مصروفات الخزنة'});if(!req.user.permissions.includes('edit_expenses'))return res.status(403).json({error:'تسجيل المصروفات يحتاج صلاحية قراءة وتعديل للمصروفات؛ صلاحية الخزنة أو التحصيل وحدها لا تكفي'});const d=req.body||{},amount=Number(d.amount),payee=String(d.payee||'').trim(),image=String(d.invoice_image||'');if(!String(d.category||'').trim()||!String(d.description||'').trim()||!payee||!Number.isFinite(amount)||amount<=0||!['cash','bank_transfer','instapay'].includes(d.method))return res.status(400).json({error:'أكمل بند المصروف والتفاصيل والمبلغ وطريقة الصرف واسم المستفيد'});if(image&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(image))return res.status(400).json({error:'صورة الفاتورة يجب أن تكون PNG أو JPG أو WEBP'});if(image&&image.length>6500000)return res.status(400).json({error:'حجم صورة الفاتورة كبير؛ اختر صورة أصغر من 4.5 ميجابايت'});const tx=db.transaction(async ()=>{const next=(await db.prepare('SELECT COALESCE(MAX(id),0)+1 n FROM cash_journal').get()).n;const entry='NS-JV-'+String(next).padStart(8,'0');const j=(await db.prepare(`INSERT INTO cash_journal(entry_no,entry_type,category,amount,method,description,payee,created_by) VALUES(?,'expense',?,?,?,?,?,?)`).run(entry,String(d.category).trim(),amount,d.method,String(d.description).trim(),payee,req.user.id));const n=(await db.prepare('SELECT COALESCE(MAX(id),0)+1 n FROM expense_receipts').get()).n;const receipt='NS-EX-'+String(n).padStart(8,'0');(await db.prepare('INSERT INTO expense_receipts(journal_id,receipt_no,payee,invoice_image) VALUES(?,?,?,?)').run(j.lastInsertRowid,receipt,payee,image||null));(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'cash_expense_receipt','cash_journal',j.lastInsertRowid,JSON.stringify({amount,category:String(d.category).trim(),payee,description:String(d.description).trim(),receipt_no:receipt,entry_no:entry})));return {ok:true,entry_no:entry,receipt_no:receipt,journal_id:j.lastInsertRowid}});try{res.json(await tx())}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/expense-receipts/:id',auth,permit('expenses'),async (req,res)=>{const r=(await db.prepare(`SELECT e.*,j.entry_no,j.category,j.amount,j.method,j.description,j.created_at,j.payee,u.full_name employee FROM expense_receipts e JOIN cash_journal j ON j.id=e.journal_id LEFT JOIN users u ON u.id=j.created_by WHERE e.id=? OR e.receipt_no=?`).get(Number(req.params.id)||-1,String(req.params.id)));if(!r)return res.status(404).json({error:'الإيصال غير موجود'});res.json(r)});
