// Automatically complete only fully paid events whose date has passed and which were never postponed/cancelled.
async function autoCompleteBookings(){const now=new Date(),today=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');const due=(await db.prepare(`SELECT b.id,b.status,b.event_date FROM bookings b WHERE b.event_date<? AND b.status IN ('confirmed','pending_payment') AND COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.booking_id=b.id AND p.payment_type!='security_refund'),0)>=(SELECT event_total+deposit-COALESCE(special_discount,0) FROM bookings WHERE id=b.id)`).all(today));const tx=db.transaction(async ()=>{for(const b of due){(await db.prepare("UPDATE bookings SET status='completed',completed_at=COALESCE(completed_at,CURRENT_TIMESTAMP) WHERE id=?").run(b.id));(await db.prepare('INSERT INTO booking_status_history(booking_id,old_status,new_status,old_event_date,new_event_date,reason,changed_by) VALUES(?,?,?,?,?,?,NULL)').run(b.id,b.status,'completed',b.event_date,b.event_date,'اكتمال تلقائي بعد انتهاء المناسبة وسداد كامل المستحقات'));}});await tx();}
app.delete('/api/bookings/:id',auth,(req,res,next)=>{if(req.user.role==='admin'||req.user.permissions.includes('delete_bookings')||req.user.permissions.includes('delete_all_data'))return next();return res.status(403).json({error:'ليس لديك صلاحية مسح الحجوزات'});},async (req,res)=>{try{const b=(await db.prepare('SELECT id,booking_no FROM bookings WHERE id=?').get(req.params.id));if(!b)return res.status(404).json({error:'الحجز غير موجود'});const financial=(await db.prepare('SELECT COUNT(*) n FROM payments WHERE booking_id=?').get(b.id)).n+(await db.prepare('SELECT COUNT(*) n FROM cash_journal WHERE booking_id=?').get(b.id)).n+(await db.prepare('SELECT COUNT(*) n FROM contractor_payouts WHERE booking_id=?').get(b.id)).n;if(financial)return res.status(409).json({error:'لا يمكن مسح هذا الحجز لأنه مرتبط بتحصيلات أو قيود مالية. استخدم سجل الحجوزات والإجراءات المالية المعتمدة بدلًا من الحذف النهائي.'});const tx=db.transaction(async ()=>{for(const t of ['booking_buffets','booking_addons','booking_operational_addons','booking_contractors','booking_status_history','booking_activity','booking_addon_sales','booking_adjustments','booking_change_requests','discount_requests','additional_discount_requests','inventory_alerts','inventory_movements']){try{(await db.prepare(`DELETE FROM ${t} WHERE booking_id=?`).run(b.id))}catch(e){if(!/no such column|no such table/i.test(e.message))throw e}}(await db.prepare('DELETE FROM bookings WHERE id=?').run(b.id));(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'delete','booking',b.id,JSON.stringify({booking_no:b.booking_no})));});await tx();res.json({ok:true})}catch(e){res.status(400).json({error:'تعذر مسح الحجز؛ لم يتم حذف أي بيانات.'})}});
app.put('/api/bookings/:id/rooms',auth,permit('bookings'),async (req,res)=>{const id=Number(req.params.id),b=(await db.prepare("SELECT * FROM bookings WHERE id=? AND status!='cancelled'").get(id));if(!b)return res.status(404).json({error:'الحجز غير موجود أو ملغي'});const ids=[...new Set((Array.isArray(req.body?.bride_room_ids)?req.body.bride_room_ids:[]).map(Number).filter(Number.isInteger))];if(ids.some(async x=>!(await db.prepare('SELECT id FROM bride_rooms WHERE id=? AND active=1').get(x))))return res.status(400).json({error:'اختيار غرفة غير صحيح'});const start=b.event_date+' 10:00';let endDate=b.event_date;if(String(b.end_time)<='10:00'){const dt=new Date(b.event_date+'T12:00:00');dt.setDate(dt.getDate()+1);endDate=dt.toISOString().slice(0,10)}const end=endDate+' '+b.end_time;for(const roomId of ids){const clash=(await db.prepare(`SELECT bb.booking_id FROM booking_bride_rooms bb JOIN bookings x ON x.id=bb.booking_id WHERE bb.room_id=? AND bb.booking_id<>? AND x.status!='cancelled' AND bb.start_at < ? AND bb.end_at > ?`).get(roomId,id,end,start));if(clash)return res.status(409).json({error:(await db.prepare('SELECT name FROM bride_rooms WHERE id=?').get(roomId)).name+' مشغولة في موعد هذا الحجز'});}const tx=db.transaction(async ()=>{(await db.prepare('DELETE FROM booking_bride_rooms WHERE booking_id=?').run(id));for(const roomId of ids)(await db.prepare('INSERT INTO booking_bride_rooms(booking_id,room_id,start_at,end_at) VALUES(?,?,?,?)').run(id,roomId,start,end));(await db.prepare('INSERT INTO booking_activity(booking_id,user_id,action,details) VALUES(?,?,?,?)').run(id,req.user.id,'bride_rooms_updated',JSON.stringify({room_ids:ids,start_at:start,end_at:end})));(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'update_bride_rooms','booking',id,JSON.stringify({room_ids:ids})));});await tx();res.json({ok:true,room_ids:ids})});
app.get('/api/occupancy-calendar',auth,permit('bookings'),async (req,res)=>{const from=String(req.query.from||new Date().toISOString().slice(0,10)),to=String(req.query.to||from);if(!/^\d{4}-\d{2}-\d{2}$/.test(from)||!/^\d{4}-\d{2}-\d{2}$/.test(to)||from>to)return res.status(400).json({error:'حدد فترة تقويم صحيحة'});const rooms=(await db.prepare('SELECT id,name FROM bride_rooms WHERE active=1 ORDER BY id').all());const rows=(await db.prepare(`SELECT b.id,b.booking_no,b.event_date,b.start_time,b.end_time,b.status,c.full_name customer_name,h.name hall_name FROM bookings b LEFT JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id WHERE b.event_date BETWEEN ? AND ? AND b.status!='cancelled' ORDER BY b.event_date,b.start_time`).all(from,to));const roomBookings=(await db.prepare(`SELECT br.id room_id,br.name room_name,bb.booking_id,bb.start_at,bb.end_at,b.booking_no,b.event_date,b.start_time,b.end_time,b.status,c.full_name customer_name,h.name hall_name FROM booking_bride_rooms bb JOIN bride_rooms br ON br.id=bb.room_id JOIN bookings b ON b.id=bb.booking_id LEFT JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id WHERE substr(bb.start_at,1,10)<=? AND substr(bb.end_at,1,10)>=? AND b.status!='cancelled' ORDER BY bb.start_at`).all(to,from));res.json({rooms,bookings:rows,roomBookings})});
app.get('/api/bookings',auth,permit('bookings'),async (req,res)=>{await autoCompleteBookings();const rows=(await db.prepare(`SELECT b.*,c.full_name customer_name,c.phone,c.phone2,c.id_number,c.address,c.contractor_name,c.bride_name,h.name hall_name,p.name package_name,COALESCE((SELECT SUM(pm.amount) FROM payments pm WHERE pm.booking_id=b.id AND pm.payment_type NOT IN ('security_deposit','security_refund')),0) paid_amount FROM bookings b LEFT JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id JOIN hall_packages p ON p.id=b.hall_package_id ORDER BY event_date DESC,start_time`).all());res.json(rows)});
app.put('/api/bookings/:id/workflow-status',auth,permit('bookings'),async (req,res)=>{const id=Number(req.params.id),stage=String(req.body?.booking_stage||'');if(!['preliminary','awaiting_manager','confirmed'].includes(stage))return res.status(400).json({error:'حالة الحجز غير صحيحة'});const b=(await db.prepare('SELECT * FROM bookings WHERE id=?').get(id));if(!b)return res.status(404).json({error:'الحجز غير موجود'});if(['cancelled','completed'].includes(b.status))return res.status(400).json({error:'لا يمكن تغيير حالة الحجز التجاري بعد إلغائه أو اكتماله'});if(stage==='awaiting_manager'){const pending=(await db.prepare("SELECT (SELECT COUNT(*) FROM discount_requests WHERE booking_id=? AND status='pending')+(SELECT COUNT(*) FROM additional_discount_requests WHERE booking_id=? AND status='pending') n").get(id,id)).n;if(!pending)return res.status(400).json({error:'لا يمكن اختيار انتظار موافقة المدير دون وجود طلب خصم معلق'});}const tx=db.transaction(async ()=>{(await db.prepare('UPDATE bookings SET booking_stage=? WHERE id=?').run(stage,id));(await db.prepare('INSERT INTO booking_activity(booking_id,user_id,action,details) VALUES(?,?,?,?)').run(id,req.user.id,'booking_stage_changed',JSON.stringify({old_stage:b.booking_stage||'preliminary',new_stage:stage,changed_by:req.user.full_name||req.user.username})));(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'booking_stage_changed','booking',id,JSON.stringify({old_stage:b.booking_stage||'preliminary',new_stage:stage})));});await tx();if(stage==='confirmed'){try{await generateBookingWorkOrders(id,req.user.id)}catch(workErr){console.error('Work orders generation after confirmation:',workErr.message)}}res.json({ok:true,booking_stage:stage,message:'تم تحديث حالة الحجز'})});

app.post('/api/bookings/:id/postpone',auth,permit('bookings'),async (req,res)=>{const id=Number(req.params.id),d=req.body||{},newDate=String(d.new_event_date||'');const b=(await db.prepare('SELECT * FROM bookings WHERE id=?').get(id));if(!b)return res.status(404).json({error:'الحجز غير موجود'});if(!/^\d{4}-\d{2}-\d{2}$/.test(newDate)||newDate<=b.event_date)return res.status(400).json({error:'تاريخ التأجيل يجب أن يكون بعد تاريخ المناسبة الحالي'});if(b.status==='cancelled'||b.status==='completed')return res.status(400).json({error:'لا يمكن تأجيل حجز ملغي أو مكتمل'});const conflict=(await db.prepare("SELECT id FROM bookings WHERE id<>? AND hall_id=? AND event_date=? AND status NOT IN ('cancelled','completed') AND NOT(end_time<=? OR start_time>=?)").get(id,b.hall_id,newDate,b.start_time,b.end_time));if(conflict)return res.status(409).json({error:'يوجد حجز آخر متعارض في القاعة والموعد الجديد'});const reason=String(d.reason||'').trim();if(!reason)return res.status(400).json({error:'اكتب سبب التأجيل'});const tx=db.transaction(async ()=>{(await db.prepare("UPDATE bookings SET postponed_from_date=COALESCE(postponed_from_date,event_date),event_date=?,status='postponed' WHERE id=?").run(newDate,id));(await db.prepare('INSERT INTO booking_status_history(booking_id,old_status,new_status,old_event_date,new_event_date,reason,notes,changed_by) VALUES(?,?,?,?,?,?,?,?)').run(id,b.status,'postponed',b.event_date,newDate,reason,String(d.notes||''),req.user.id));(await db.prepare('INSERT INTO booking_activity(booking_id,user_id,action,details) VALUES(?,?,?,?)').run(id,req.user.id,'postpone_booking',JSON.stringify({old_event_date:b.event_date,new_event_date:newDate,reason})));(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'postpone_booking','booking',id))});await tx();res.json({ok:true,message:'تم تأجيل الحجز وتسجيل الموعد الجديد'})});
app.post('/api/bookings/:id/cancel',auth,permit('bookings'),async (req,res)=>{const id=Number(req.params.id),reason=String((req.body||{}).reason||'').trim(),notes=String((req.body||{}).notes||'').trim();const b=(await db.prepare('SELECT * FROM bookings WHERE id=?').get(id));if(!b)return res.status(404).json({error:'الحجز غير موجود'});if(!reason)return res.status(400).json({error:'سبب الإلغاء التفصيلي إجباري'});if(b.status==='completed')return res.status(400).json({error:'لا يمكن إلغاء حجز مكتمل'});if(b.status==='cancelled')return res.status(400).json({error:'الحجز ملغي بالفعل'});const tx=db.transaction(async ()=>{(await db.prepare("UPDATE bookings SET status='cancelled',cancel_reason=? WHERE id=?").run(reason,id));(await db.prepare('INSERT INTO booking_status_history(booking_id,old_status,new_status,old_event_date,new_event_date,reason,notes,changed_by) VALUES(?,?,?,?,?,?,?,?)').run(id,b.status,'cancelled',b.event_date,b.event_date,reason,notes,req.user.id));(await db.prepare('INSERT INTO booking_activity(booking_id,user_id,action,details) VALUES(?,?,?,?)').run(id,req.user.id,'cancel_booking',JSON.stringify({reason,notes})));(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'cancel_booking','booking',id))});await tx();await cancelBookingWorkOrders(id,req.user.id,reason);res.json({ok:true,message:'تم إلغاء الحجز وتسجيل السبب وإلغاء أوامر الشغل المرتبطة'})});
app.get('/api/booking-status-history/:id',auth,permit('bookings'),async (req,res)=>res.json((await db.prepare('SELECT x.*,u.full_name employee FROM booking_status_history x LEFT JOIN users u ON u.id=x.changed_by WHERE x.booking_id=? ORDER BY x.id DESC').all(req.params.id))));
app.get('/api/reports/employee-sales',auth,async (req,res)=>{ /* Every employee may see their own activity; cross-employee reports require reports permission or admin. */const from=String(req.query.from||'0001-01-01'),to=String(req.query.to||'9999-12-31'),requestedUserId=Number(req.query.user_id||0),userId=(req.user.role==='admin'||req.user.permissions.includes('reports'))?requestedUserId:req.user.id,bookingNo=String(req.query.booking_no||'').trim();let where="date(s.created_at)>=date(?) AND date(s.created_at)<=date(?)",params=[from,to];if(userId){where+=' AND s.user_id=?';params.push(userId)}if(bookingNo){where+=' AND b.booking_no LIKE ?';params.push('%'+bookingNo+'%')}const sales=(await db.prepare(`SELECT s.*,u.full_name employee,b.booking_no,b.event_date,c.full_name customer_name FROM booking_addon_sales s LEFT JOIN users u ON u.id=s.user_id JOIN bookings b ON b.id=s.booking_id LEFT JOIN customers c ON c.id=b.customer_id WHERE ${where} ORDER BY s.created_at DESC,s.id DESC`).all(...params));let activityWhere="date(a.created_at)>=date(?) AND date(a.created_at)<=date(?)";let ap=[from,to];if(userId){activityWhere+=' AND a.user_id=?';ap.push(userId)}if(bookingNo){activityWhere+=' AND b.booking_no LIKE ?';ap.push('%'+bookingNo+'%')}const activities=(await db.prepare(`SELECT a.*,u.full_name employee,b.booking_no,b.event_date,c.full_name customer_name FROM booking_activity a LEFT JOIN users u ON u.id=a.user_id JOIN bookings b ON b.id=a.booking_id LEFT JOIN customers c ON c.id=b.customer_id WHERE ${activityWhere} ORDER BY a.created_at DESC,a.id DESC`).all(...ap));const users=(req.user.role==='admin'||req.user.permissions.includes('reports'))?(await db.prepare("SELECT id,full_name,username FROM users WHERE active=1 ORDER BY full_name").all()):(await db.prepare("SELECT id,full_name,username FROM users WHERE id=? AND active=1").all(req.user.id));const byEmployee=new Map();for(const u of users)byEmployee.set(u.id,{user_id:u.id,employee:u.full_name,username:u.username,bookings_created:0,bookings_touched:0,addons_added:0,sales_total:0,removed_value:0,net_changes:0,bookings:[]});for(const a of activities){if(!a.user_id)continue;const x=byEmployee.get(a.user_id)||{user_id:a.user_id,employee:a.employee||'غير معروف',username:'',bookings_created:0,bookings_touched:0,addons_added:0,sales_total:0,removed_value:0,net_changes:0,bookings:[]};x.bookings_touched++;if(a.action==='create_booking')x.bookings_created++;if(!x.bookings.includes(a.booking_no))x.bookings.push(a.booking_no);byEmployee.set(a.user_id,x)}for(const s of sales){if(!s.user_id)continue;const x=byEmployee.get(s.user_id)||{user_id:s.user_id,employee:s.employee||'غير معروف',username:'',bookings_created:0,bookings_touched:0,addons_added:0,sales_total:0,removed_value:0,net_changes:0,bookings:[]};if(s.change_type==='add'||(s.change_type==='quantity_change'&&Number(s.quantity_delta)>0)){x.addons_added+=Math.max(0,Number(s.quantity_delta));x.sales_total+=Math.max(0,Number(s.sales_delta))}if(s.change_type==='remove')x.removed_value+=Math.abs(Number(s.sales_delta));x.net_changes+=Number(s.sales_delta||0);if(!x.bookings.includes(s.booking_no))x.bookings.push(s.booking_no);byEmployee.set(s.user_id,x)}const employeeSummary=[...byEmployee.values()].filter(x=>x.bookings_touched||x.addons_added||x.bookings.length).map(x=>({...x,booking_count:x.bookings.length})).sort((a,b)=>b.sales_total-a.sales_total);const summary={sales_total:sales.reduce((n,x)=>n+Number(x.sales_delta||0),0),positive_sales:sales.filter(x=>x.change_type==='add'||(x.change_type==='quantity_change'&&Number(x.quantity_delta)>0)).reduce((n,x)=>n+Math.max(0,Number(x.sales_delta||0)),0),employees:new Set([...sales,...activities].map(x=>x.user_id).filter(Boolean)).size,bookings:new Set([...sales,...activities].map(x=>x.booking_id)).size};res.json({sales,activities,users,summary,employeeSummary,from,to,user_id:userId,booking_no:bookingNo})});
