app.get('/api/collection/:id/history',auth,permit('finance'),async (req,res)=>{const b=(await db.prepare(`SELECT b.*,c.full_name customer_name,c.phone,h.name hall_name,p.name package_name FROM bookings b LEFT JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id JOIN hall_packages p ON p.id=b.hall_package_id WHERE b.id=?`).get(req.params.id));if(!b)return res.status(404).json({error:'الحجز غير موجود'});const rows=(await db.prepare(`SELECT p.id,p.amount,p.payment_type,p.paid_at,p.received_by,u.full_name receiver,p.notes,p.receipt_no,p.method,p.reference,p.receipt_reprints FROM payments p LEFT JOIN users u ON u.id=p.received_by WHERE p.booking_id=? ORDER BY p.id DESC`).all(b.id)).map(p=>({...p,receipt_no:p.receipt_no||('NS-RC-'+String(p.id).padStart(8,'0'))}));const paid=(await db.prepare("SELECT COALESCE(SUM(amount),0) n FROM payments WHERE booking_id=? AND payment_type!='security_refund'").get(b.id)).n;const paidContract=(await db.prepare("SELECT COALESCE(SUM(amount),0) n FROM payments WHERE booking_id=? AND payment_type NOT IN ('security_deposit','security_refund')").get(b.id)).n;const types=(await db.prepare('SELECT payment_type,COUNT(*) n FROM payments WHERE booking_id=? GROUP BY payment_type').all(b.id)).reduce((o,x)=>(o[x.payment_type]=x.n,o),{});res.json({booking:b,payments:rows,paid_total:paid,paid_contract:paidContract,remaining_total:Math.max(0,Number(b.event_total)+Number(b.deposit)-Number(b.special_discount||0)-paid),recorded_types:types})});
app.get('/api/collection/receipt-by-no/:receiptNo',auth,permit('cashbox'),async (req,res)=>{const receipt=String(req.params.receiptNo||'').trim();const row=(await db.prepare(`SELECT p.id payment_id,p.booking_id,p.receipt_no,p.payment_type,p.amount,p.paid_at,p.notes,b.booking_no,b.event_date,c.full_name customer_name,c.phone,COALESCE((SELECT SUM(x.amount) FROM payments x WHERE x.booking_id=b.id AND x.payment_type='security_deposit'),0) security_held,COALESCE((SELECT SUM(x.amount) FROM payments x WHERE x.booking_id=b.id AND x.payment_type='security_refund'),0) security_refunded FROM payments p JOIN bookings b ON b.id=p.booking_id LEFT JOIN customers c ON c.id=b.customer_id WHERE p.receipt_no=?`).get(receipt));if(!row)return res.status(404).json({error:'لم يتم العثور على إيصال بهذا الرقم.'});res.json(row)});
app.post('/api/collection/receipt/:paymentId/reprint',auth,financeWrite,async (req,res)=>{try{const id=Number(req.params.paymentId);const tx=db.transaction(async ()=>{const row=(await db.prepare('SELECT id,receipt_no,receipt_reprints FROM payments WHERE id=?').get(id));if(!row)throw Object.assign(new Error('الإيصال غير موجود'),{status:404});const used=Number(row.receipt_reprints||0);if(used>=2)throw Object.assign(new Error('تم استخدام مرتي إعادة الطباعة المسموحتين لهذا الإيصال.'),{status:409});const changed=(await db.prepare('UPDATE payments SET receipt_reprints=COALESCE(receipt_reprints,0)+1 WHERE id=? AND COALESCE(receipt_reprints,0)<2').run(id));if(!changed.changes)throw Object.assign(new Error('تم استهلاك الحد المسموح لإعادة الطباعة.'),{status:409});const updated=(await db.prepare('SELECT receipt_reprints FROM payments WHERE id=?').get(id));(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'reprint_collection_receipt','payment',id,JSON.stringify({receipt_no:row.receipt_no,reprint_number:updated.receipt_reprints})));return {ok:true,reprints_used:updated.receipt_reprints,reprints_left:Math.max(0,2-updated.receipt_reprints)}});res.json(await tx())}catch(e){res.status(e.status||400).json({error:e.message})}});
app.get('/api/collection/receipt/:paymentId',auth,permit('finance'),async (req,res)=>{const row=(await db.prepare(`SELECT p.*,u.full_name receiver,b.booking_no,b.event_date,b.start_time,b.end_time,b.guest_count,b.event_total,b.deposit,(b.event_total+b.deposit-COALESCE(b.special_discount,0)) final_total,b.special_discount,COALESCE((SELECT r.id FROM additional_discount_requests r WHERE r.booking_id=b.id AND r.status='approved' ORDER BY r.id DESC LIMIT 1),0) additional_discount_request_id,b.package_price,b.discount,b.buffet_total,b.addons_total,b.service_rate,b.service_total,b.free_meals,(SELECT ho.name FROM hall_offers ho WHERE ho.id=b.offer_id) offer_name,COALESCE((SELECT SUM(bo.line_total) FROM booking_operational_addons bo WHERE bo.booking_id=b.id),0) operational_total,c.full_name customer_name,c.phone,c.id_number,c.nationality,h.name hall_name,hp.name package_name,COALESCE((SELECT SUM(x.amount) FROM payments x WHERE x.booking_id=b.id AND x.payment_type!='security_refund' AND x.id<=p.id),0) paid_after,COALESCE((SELECT SUM(x.amount) FROM payments x WHERE x.booking_id=b.id AND x.payment_type NOT IN ('security_deposit','security_refund')),0) paid_contract,COALESCE((SELECT SUM(x.amount) FROM payments x WHERE x.booking_id=b.id AND x.payment_type!='security_refund' AND x.id<=p.id),0) paid_total,COALESCE((SELECT SUM(x.amount) FROM payments x WHERE x.booking_id=b.id AND x.payment_type='security_deposit' AND x.id<=p.id),0) security_paid,COALESCE((SELECT SUM(x.amount) FROM payments x WHERE x.booking_id=b.id AND x.payment_type='security_deposit'),0) security_held,COALESCE((SELECT SUM(x.amount) FROM payments x WHERE x.booking_id=b.id AND x.payment_type='security_refund' AND x.id<=p.id),0) security_refunded FROM payments p JOIN bookings b ON b.id=p.booking_id LEFT JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id JOIN hall_packages hp ON hp.id=b.hall_package_id LEFT JOIN users u ON u.id=p.received_by WHERE p.id=?`).get(req.params.paymentId));if(!row)return res.status(404).json({error:'الإيصال غير موجود'});res.json(row)});
app.post('/api/collection/:id/payment',auth,financeWrite,async (req,res)=>{
 const b=(await db.prepare('SELECT * FROM bookings WHERE id=?').get(req.params.id));if(!b)return res.status(404).json({error:'الحجز غير موجود'});if(b.status==='cancelled')return res.status(400).json({error:'لا يمكن تسجيل تحصيل لحجز ملغي'});
 const {amount,payment_type='installment_1',method='cash',notes='',reference=''}=req.body||{};const validInstallment=/^installment_(10|[1-9])$/.test(payment_type);const paidBefore=(await db.prepare("SELECT COALESCE(SUM(amount),0) n FROM payments WHERE booking_id=? AND payment_type!='security_refund'").get(b.id)).n;const calculatedAmount=payment_type==='total_due'?Math.max(0,Number(b.event_total)+Number(b.deposit)-Number(b.special_discount||0)-paidBefore):Number(amount);const n=Math.round(calculatedAmount*100)/100;if(!Number.isFinite(n)||n<=0)return res.status(400).json({error:'أدخل مبلغًا صحيحًا أكبر من صفر'});if(!['booking_deposit','security_deposit','security_refund','total_due'].includes(payment_type)&&!validInstallment)return res.status(400).json({error:'نوع التحصيل غير صحيح'});if(!['cash','instapay','visa','bank_transfer'].includes(method))return res.status(400).json({error:'طريقة التحصيل غير صحيحة'});
 const tx=db.transaction(async ()=>{
  const countType=(await db.prepare('SELECT COUNT(*) n FROM payments WHERE booking_id=? AND payment_type=?').get(b.id,payment_type)).n;
  if((['booking_deposit','security_deposit','total_due'].includes(payment_type)||validInstallment)&&countType>0)throw new Error(payment_type==='booking_deposit'?'تم تسجيل مقدم الحجز بالفعل؛ اختر دفعة تعاقد للدفعات التالية.':'تم تسجيل التأمين بالفعل؛ لا يمكن تسجيله مرة أخرى.');
  if(payment_type==='security_refund'){const held=(await db.prepare("SELECT COALESCE(SUM(amount),0) n FROM payments WHERE booking_id=? AND payment_type='security_deposit'").get(b.id)).n;const refunded=(await db.prepare("SELECT COALESCE(SUM(amount),0) n FROM payments WHERE booking_id=? AND payment_type='security_refund'").get(b.id)).n;if(held-refunded<n-0.001)throw new Error('قيمة رد التأمين أكبر من التأمين المستلم والمتبقي.');}
  if(['booking_deposit','security_deposit','installment','total_due'].includes(payment_type)||validInstallment){const paid=(await db.prepare("SELECT COALESCE(SUM(amount),0) n FROM payments WHERE booking_id=? AND payment_type!='security_refund'").get(b.id)).n;const remaining=Math.max(0,Number(b.event_total)+Number(b.deposit)-Number(b.special_discount||0)-paid);if(n>remaining+0.001)throw new Error(`المبلغ أكبر من المتبقي من الإجمالي شامل التأمين (${remaining.toFixed(2)} جنيه).`);if(payment_type==='booking_deposit'&&(await db.prepare("SELECT COUNT(*) n FROM payments WHERE booking_id=? AND payment_type='booking_deposit'").get(b.id)).n>0)throw new Error('تم تسجيل مقدم الحجز بالفعل؛ اختر دفعة تعاقد للدفعات التالية.');if(payment_type==='security_deposit'){const already=(await db.prepare("SELECT COALESCE(SUM(amount),0) n FROM payments WHERE booking_id=? AND payment_type='security_deposit'").get(b.id)).n;if(already+n>Number(b.deposit)+0.001)throw new Error('مبلغ التأمين يتجاوز التأمين المحدد للحجز.');}}
  if((payment_type==='installment'||validInstallment||payment_type==='total_due')&&(await db.prepare("SELECT COUNT(*) n FROM payments WHERE booking_id=? AND payment_type='booking_deposit'").get(b.id)).n===0)throw new Error('سجّل مقدم الحجز أولًا قبل تسجيل دفعات التعاقد.');
  if(payment_type==='total_due'&&Math.abs(n-Math.max(0,Number(b.event_total)+Number(b.deposit)-Number(b.special_discount||0)-paidBefore))>0.001)throw new Error('تم تحديث الرصيد؛ أعد تحميل الحساب قبل تسجيل إجمالي المستحق.');const methodLabel={cash:'كاش',instapay:'إنستا باي',visa:'فيزا / POS',bank_transfer:'تحويل بنكي'}[method];const next=(await db.prepare('SELECT COALESCE(MAX(id),0)+1 n FROM payments').get()).n;const receipt='NS-RC-'+String(next).padStart(8,'0');
  const info=(await db.prepare('INSERT INTO payments(booking_id,amount,payment_type,received_by,notes,receipt_no,method,reference) VALUES(?,?,?,?,?,?,?,?)').run(b.id,n,payment_type,req.user.id,String(notes||''),receipt,methodLabel,String(reference||'')));(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'receive_cash_'+payment_type,'payment',info.lastInsertRowid,JSON.stringify({amount:n,payment_type,receipt_no:receipt,method:methodLabel,reference:String(reference||''),booking_no:b.booking_no,customer_name:(await db.prepare('SELECT full_name FROM customers WHERE id=?').get(b.customer_id))?.full_name||''})));const jn=(await db.prepare('SELECT COALESCE(MAX(id),0)+1 n FROM cash_journal').get()).n;(await db.prepare(`INSERT INTO cash_journal(entry_no,entry_type,category,amount,method,description,booking_id,payment_id,created_by) VALUES(?,?,?,?,?,?,?,?,?)`).run('NS-JV-'+String(jn).padStart(8,'0'),payment_type==='security_refund'?'expense':'income',payment_type,n,methodLabel,`${payment_type==='security_refund'?'رد تأمين':'تحصيل'} للحجز ${b.booking_no}`,b.id,info.lastInsertRowid,req.user.id));
  // تحديث حالة التحصيل تلقائيًا بعد تسجيل الإيصال، مع استبعاد التأمين المسترد من إجمالي المدفوع.
  if(payment_type!=='security_refund'){const totals=(await db.prepare("SELECT COALESCE(SUM(CASE WHEN payment_type!='security_refund' THEN amount ELSE 0 END),0) paid FROM payments WHERE booking_id=?").get(b.id));const due=Math.max(0,Number(b.event_total)+Number(b.deposit)-Number(b.special_discount||0));if(Number(totals.paid)+0.001>=due&&b.status==='pending_payment'){(await db.prepare("UPDATE bookings SET status='confirmed' WHERE id=? AND status='pending_payment'").run(b.id));(await db.prepare('INSERT INTO booking_status_history(booking_id,old_status,new_status,old_event_date,new_event_date,reason,changed_by) VALUES(?,?,?,?,?,?,?)').run(b.id,'pending_payment','confirmed',b.event_date,b.event_date,'تحديث تلقائي بعد سداد كامل المستحقات',req.user.id));}}
  return {payment_id:info.lastInsertRowid,receipt_no:receipt};
 });try{const r=await tx();res.json({ok:true,...r,received_by:req.user.full_name,amount:n,method,reference})}catch(e){res.status(400).json({error:e.message})}
});
app.delete('/api/collection/payments/:id',auth,(req,res,next)=>{if(req.user.role==='admin'||req.user.permissions.includes('delete_collections')||req.user.permissions.includes('delete_all_data'))return next();return res.status(403).json({error:'ليس لديك صلاحية مسح سجلات التحصيل'});},async (req,res)=>{try{const p=(await db.prepare('SELECT * FROM payments WHERE id=?').get(req.params.id));if(!p)return res.status(404).json({error:'دفعة التحصيل غير موجودة'});if(p.payment_type==='security_refund')return res.status(409).json({error:'لا يمكن مسح رد التأمين من السجل مباشرة؛ راجع الإدارة المالية لتصحيح الحركة.'});const tx=db.transaction(async ()=>{const linked=(await db.prepare('DELETE FROM cash_journal WHERE payment_id=?').run(p.id)).changes;if(!linked){const category=p.payment_type==='booking_deposit'?'مقدم حجز':p.payment_type==='security_deposit'?'تأمين مسترد':p.payment_type;const legacy=(await db.prepare('SELECT id FROM cash_journal WHERE booking_id=? AND payment_id IS NULL AND category=? AND amount=? ORDER BY id LIMIT 1').get(p.booking_id,category,p.amount));if(legacy)(await db.prepare('DELETE FROM cash_journal WHERE id=?').run(legacy.id));}(await db.prepare('DELETE FROM payments WHERE id=?').run(p.id));const b=(await db.prepare('SELECT id,event_total,deposit,special_discount,status,event_date FROM bookings WHERE id=?').get(p.booking_id));if(b){const paid=(await db.prepare("SELECT COALESCE(SUM(amount),0) n FROM payments WHERE booking_id=? AND payment_type!='security_refund'").get(b.id)).n;const due=Number(b.event_total)+Number(b.deposit)-Number(b.special_discount||0);if(paid+0.001<due&&b.status==='confirmed')(await db.prepare("UPDATE bookings SET status='pending_payment' WHERE id=? AND status='confirmed'").run(b.id));}(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'delete','payment',p.id,JSON.stringify({booking_id:p.booking_id,amount:p.amount,payment_type:p.payment_type,receipt_no:p.receipt_no})));});await tx();res.json({ok:true})}catch(e){res.status(400).json({error:'تعذر مسح دفعة التحصيل؛ لم يتم تغيير البيانات.'})}});

// PostgreSQL backup/restore must use Supabase's database backup/export workflow; SQLite file restore is intentionally disabled after migration.
app.get('/api/backup',auth,(req,res)=>{if(req.user.role!=='admin')return res.status(403).json({error:'النسخ الاحتياطي متاح لمدير النظام فقط'});res.status(501).json({error:'نسخ PostgreSQL الاحتياطي يتم من Supabase. تنزيل ملف SQLite لم يعد مدعومًا بعد التحويل.'})});
app.post('/api/backup/restore',auth,async (req,res)=>{if(req.user.role!=='admin')return res.status(403).json({error:'استعادة النسخة متاحة لمدير النظام فقط'});res.status(501).json({error:'استعادة SQLite غير مدعومة على قاعدة PostgreSQL. استخدم خطة الاستعادة المعتمدة لـ Supabase بعد التحقق من النسخة.'})});

app.get('/api/health',async (req,res)=>{try{await db.prepare('SELECT 1 ok').get();res.json({ok:true,database:'supabase-postgresql',schema:'nasim',timestamp:new Date().toISOString()})}catch(e){res.status(503).json({ok:false,database:'supabase-postgresql',error:'Database unavailable'})}});app.use(express.static(path.join(__dirname,'public')));

app.get('/api/inventory/report',auth,permit('inventory'),async (req,res)=>{const from=String(req.query.from||'0001-01-01'),to=String(req.query.to||'9999-12-31'),itemId=Number(req.query.item_id||0);try{const params=[from,to];let filter='date(m.created_at)>=date(?) AND date(m.created_at)<=date(?)';if(itemId){filter+=' AND i.id=?';params.push(itemId)}const rows=(await db.prepare(`SELECT i.id item_id,i.name item_name,i.unit, SUM(CASE WHEN m.movement_type='in' THEN m.quantity ELSE 0 END) incoming, SUM(CASE WHEN m.movement_type IN ('out','booking_reserve') THEN m.quantity ELSE 0 END) total_out, SUM(CASE WHEN m.movement_type IN ('out','booking_reserve') AND (m.notes LIKE 'إضافة بوفيه:%') THEN m.quantity ELSE 0 END) addon_out, SUM(CASE WHEN m.movement_type IN ('out','booking_reserve') AND (m.notes NOT LIKE 'إضافة بوفيه:%') THEN m.quantity ELSE 0 END) menu_out, COUNT(m.id) movement_count FROM inventory_items i LEFT JOIN inventory_movements m ON m.item_id=i.id AND ${filter} GROUP BY i.id ORDER BY i.name`).all(...params));const movements=(await db.prepare(`SELECT m.created_at,m.item_id,i.name item_name,i.unit,m.movement_type,m.quantity,m.balance_after,m.notes,b.booking_no,u.full_name employee FROM inventory_movements m JOIN inventory_items i ON i.id=m.item_id LEFT JOIN bookings b ON b.id=m.booking_id LEFT JOIN users u ON u.id=m.created_by WHERE ${filter} ORDER BY m.created_at DESC,m.id DESC`).all(...params));res.json({from,to,rows,movements})}catch(e){res.status(500).json({error:'تعذر إنشاء تقرير المخزن: '+e.message})}});

