app.get('/api/cashier/booking-lookup',auth,async (req,res)=>{if(req.user.role!=='admin'&&req.user.role!=='cashier'&&!req.user.permissions.includes('cashbox')&&!req.user.permissions.includes('finance'))return res.status(403).json({error:'ليس لديك صلاحية الاستعلام المالي'});const phone=String(req.query.phone||'').replace(/\D/g,'');if(phone.length<7)return res.status(400).json({error:'اكتب رقم موبايل صحيحًا'});const rows=(await db.prepare(`SELECT b.id,b.booking_no,b.event_date,b.start_time,b.end_time,b.status,b.event_total,b.deposit,b.amount_due,b.guest_count,c.full_name customer_name,c.phone,h.name hall_name,p.name package_name,COALESCE((SELECT SUM(amount) FROM payments WHERE booking_id=b.id AND payment_type NOT IN ('security_refund')),0) paid_amount,COALESCE((SELECT SUM(amount) FROM booking_adjustments WHERE booking_id=b.id),0) adjustments_total,(SELECT group_concat(note_line, char(10)) FROM (SELECT (CASE WHEN r.change_type='change_date' THEN 'تغيير موعد معتمد' WHEN r.change_type='cancel' THEN 'إلغاء حجز معتمد' ELSE CASE WHEN r.item_action='add' THEN 'إضافة صنف معتمدة' ELSE 'إلغاء صنف معتمد' END END)||' — القرار: '||(CASE WHEN r.status='approved' THEN 'موافق عليه' ELSE 'مرفوض' END)||' — السبب: '||r.reason||' — ملاحظة المدير: '||COALESCE(r.review_note,'بدون ملاحظة')||' — المبلغ: '||CAST(COALESCE(r.amount,0) AS TEXT)||' ج.م' note_line FROM booking_change_requests r WHERE r.booking_id=b.id AND r.status IN ('approved','rejected') ORDER BY r.id DESC LIMIT 5)) change_notes FROM bookings b JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id JOIN hall_packages p ON p.id=b.hall_package_id WHERE REPLACE(REPLACE(REPLACE(REPLACE(c.phone,' ',''),'-',''),'+',''),'(', '') LIKE ? ORDER BY b.event_date DESC LIMIT 20`).all('%'+phone.slice(-10)+'%'));res.json(rows)});

// Inventory module: receipts, adjustments, movement ledger, and low-stock alerts.
app.get('/api/inventory',auth,permit('inventory'),async (req,res)=>{const items=(await db.prepare(`SELECT i.*,b.name buffet_item_name,a.name addon_name,COALESCE((SELECT SUM(shortage_qty) FROM inventory_alerts al WHERE al.item_id=i.id AND al.status='open'),0) shortage_open FROM inventory_items i LEFT JOIN buffet_items b ON b.id=i.buffet_item_id LEFT JOIN addons a ON a.id=i.addon_id ORDER BY i.name`).all());const buffetItems=(await db.prepare('SELECT id,name,active FROM buffet_items ORDER BY name').all());const buffetAddons=(await db.prepare('SELECT id,name,active FROM addons ORDER BY name').all());const alerts=(await db.prepare(`SELECT a.*,i.name item_name,i.unit,b.booking_no FROM inventory_alerts a JOIN inventory_items i ON i.id=a.item_id LEFT JOIN bookings b ON b.id=a.booking_id WHERE a.status='open' ORDER BY a.id DESC LIMIT 100`).all());const movements=(await db.prepare(`SELECT m.*,i.name item_name,i.unit,u.full_name employee,b.booking_no FROM inventory_movements m JOIN inventory_items i ON i.id=m.item_id LEFT JOIN users u ON u.id=m.created_by LEFT JOIN bookings b ON b.id=m.booking_id ORDER BY m.id DESC LIMIT 100`).all());res.json({items,buffetItems,buffetAddons,alerts,movements})});
app.post('/api/inventory/items',auth,permit('inventory'),async (req,res)=>{try{const d=req.body||{};if(!String(d.name||'').trim())return res.status(400).json({error:'اكتب اسم الصنف'});const sourceType=d.source_type==='addon'?'addon':'menu';const linkId=Number(d.link_id||d.buffet_item_id||0);if(linkId&&sourceType==='menu'&&!(await db.prepare('SELECT id FROM buffet_items WHERE id=?').get(linkId)))return res.status(400).json({error:'صنف المنيو المختار غير موجود'});if(linkId&&sourceType==='addon'&&!(await db.prepare('SELECT id FROM addons WHERE id=?').get(linkId)))return res.status(400).json({error:'إضافة البوفيه المختارة غير موجودة'});const qty=Number(d.stock),min=Number(d.min_stock);if(!Number.isFinite(qty)||qty<0||!Number.isFinite(min)||min<0)return res.status(400).json({error:'الرصيد وحد التنبيه يجب أن يكونا أرقامًا صحيحة غير سالبة'});const x=(await db.prepare('INSERT INTO inventory_items(name,unit,stock,min_stock,buffet_item_id,addon_id,source_type,units_per_buffet_unit) VALUES(?,?,?,?,?,?,?,?)').run(String(d.name).trim(),String(d.unit||'قطعة').trim(),qty,min,linkId&&sourceType==='menu'?linkId:null,linkId&&sourceType==='addon'?linkId:null,sourceType,Math.max(0.0001,Number(d.units_per_buffet_unit)||1)));if(qty)(await db.prepare("INSERT INTO inventory_movements(item_id,movement_type,quantity,balance_after,notes,created_by) VALUES(?,'in',?,?,?,?)").run(x.lastInsertRowid,qty,qty,'رصيد افتتاحي',req.user.id));(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'inventory_item_created','inventory_item',x.lastInsertRowid));res.json({ok:true,id:x.lastInsertRowid})}catch(e){res.status(400).json({error:e.message.includes('UNIQUE')?'اسم الصنف مسجل بالفعل':e.message})}});
app.delete('/api/inventory/items/:id',auth,(req,res,next)=>{if(req.user.role==='admin'||req.user.permissions.includes('delete_inventory')||req.user.permissions.includes('delete_all_data'))return next();return res.status(403).json({error:'ليس لديك صلاحية مسح أصناف المخزن'});},async (req,res)=>{try{const item=(await db.prepare('SELECT id,name FROM inventory_items WHERE id=?').get(req.params.id));if(!item)return res.status(404).json({error:'الصنف غير موجود'});const linked=(await db.prepare('SELECT COUNT(*) n FROM inventory_movements WHERE item_id=?').get(item.id)).n+(await db.prepare('SELECT COUNT(*) n FROM inventory_alerts WHERE item_id=?').get(item.id)).n;if(linked)return res.status(409).json({error:'لا يمكن مسح الصنف لأن له حركات أو تنبيهات مسجلة. للحفاظ على سجل المخزن، عطّله بدلًا من مسح تاريخه.'});(await db.prepare('DELETE FROM inventory_items WHERE id=?').run(item.id));(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'delete','inventory_item',item.id,JSON.stringify({name:item.name})));res.json({ok:true})}catch(e){res.status(400).json({error:'تعذر مسح الصنف؛ قد يكون مرتبطًا ببيانات أخرى.'})}});
app.post('/api/inventory/items/:id/movement',auth,permit('inventory'),async (req,res)=>{try{const d=req.body||{},qty=Number(d.quantity),type=d.type;if(!['in','out','adjustment'].includes(type)||!Number.isFinite(qty)||qty<=0)return res.status(400).json({error:'حدد نوع الحركة وكمية صحيحة أكبر من صفر'});const tx=db.transaction(async ()=>{const item=(await db.prepare('SELECT * FROM inventory_items WHERE id=? AND active=1').get(req.params.id));if(!item)throw Error('الصنف غير موجود');let balance=type==='in'?item.stock+qty:type==='out'?item.stock-qty:qty;if(balance<0)throw Error('الرصيد غير كافٍ. المتاح '+item.stock+' '+item.unit);(await db.prepare('UPDATE inventory_items SET stock=? WHERE id=?').run(balance,item.id));(await db.prepare('INSERT INTO inventory_movements(item_id,movement_type,quantity,balance_after,notes,created_by) VALUES(?,?,?,?,?,?)').run(item.id,type,qty,balance,String(d.notes||''),req.user.id));(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id) VALUES(?,?,?,?)').run(req.user.id,'inventory_'+type,'inventory_item',item.id));return {ok:true,balance}});res.json(await tx())}catch(e){res.status(400).json({error:e.message})}});
