app.get('/api/work-orders',auth,permit('work_orders'),async (req,res)=>{try{for(const cb of (await db.prepare("SELECT id,cancel_reason FROM bookings WHERE status='cancelled'").all()))await cancelBookingWorkOrders(cb.id,req.user.id,cb.cancel_reason||'تم إلغاء الحجز');const from=String(req.query.from||'0001-01-01'),to=String(req.query.to||'9999-12-31'),type=String(req.query.type||''),status=String(req.query.status||''),q=String(req.query.q||'').trim();const bookingPhone=String(req.query.booking_phone||'').trim();const bookingIdFilter=Number(req.query.booking_id)||0;let sql=`SELECT wo.*,b.booking_no,b.event_date,b.start_time,b.end_time,b.guest_count,b.status booking_status,b.booking_stage,c.full_name customer_name,h.name hall_name,p.name package_name,co.full_name contractor_name,co.job_title contractor_job,c.phone customer_phone FROM work_orders wo JOIN bookings b ON b.id=wo.booking_id LEFT JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id JOIN hall_packages p ON p.id=b.hall_package_id LEFT JOIN contractors co ON co.id=wo.contractor_id WHERE date(b.event_date)>=date(?) AND date(b.event_date)<=date(?)`;const params=[from,to];if(bookingIdFilter>0){sql+=' AND wo.booking_id=?';params.push(bookingIdFilter)}if(type){sql+=' AND wo.order_type=?';params.push(type)}if(status){sql+=' AND wo.status=?';params.push(status)}if(q){sql+=' AND (wo.serial_no LIKE ? OR b.booking_no LIKE ? OR c.full_name LIKE ? OR c.phone LIKE ? OR h.name LIKE ? OR co.full_name LIKE ?)';params.push(...Array(6).fill('%'+q+'%'))}sql+=' ORDER BY b.event_date, b.start_time, wo.id';const rows=await Promise.all((await db.prepare(sql).all(...params)).map(async o=>({...o,lines:(await db.prepare('SELECT * FROM work_order_lines WHERE work_order_id=? ORDER BY id').all(o.id))})));const bookingSql=`SELECT b.id,b.booking_no,b.event_date,b.start_time,b.end_time,b.guest_count,b.status,b.booking_stage,c.full_name customer_name,c.phone customer_phone,h.name hall_name,p.name package_name FROM bookings b LEFT JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id JOIN hall_packages p ON p.id=b.hall_package_id WHERE b.status!='cancelled' ${bookingPhone ? "AND REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(c.phone,''),' ',''),'-',''),'+',''),'(','') LIKE ?" : ''} ORDER BY b.event_date DESC LIMIT 500`;const bookings=bookingPhone?(await db.prepare(bookingSql).all('%'+bookingPhone.replace(/[\s()+-]/g,'')+'%')):(await db.prepare(bookingSql).all());res.json({rows,bookings,contractors:(await db.prepare('SELECT c.id,c.full_name,c.job_title,c.hall_id,h.name hall_name,c.cost_per_booking FROM contractors c JOIN halls h ON h.id=c.hall_id WHERE c.active=1 ORDER BY c.job_title,c.full_name').all())})}catch(e){res.status(500).json({error:'تعذر تحميل أوامر الشغل: '+e.message})}});
app.post('/api/work-orders/generate/:bookingId',auth,permit('work_orders'),async (req,res)=>{try{const b=(await db.prepare('SELECT * FROM bookings WHERE id=?').get(Number(req.params.bookingId)));if(!b)return res.status(404).json({error:'الحجز غير موجود'});if(b.status==='cancelled')return res.status(400).json({error:'لا يمكن إصدار أوامر شغل لحجز ملغي'});if(b.booking_stage!=='confirmed')return res.status(400).json({error:'لازم يكون الحجز مؤكدًا قبل إصدار أوامر الشغل'});const result=await generateBookingWorkOrders(b.id,req.user.id);(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'work_orders_generated','booking',b.id,JSON.stringify({created:result.created})));res.json({ok:true,...result,message:result.created?'تم إصدار/تحديث أوامر الشغل':'تمت مراجعة أوامر الشغل'})}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/work-orders/assign-contractor/:bookingId',auth,permit('work_orders'),async (req,res)=>{try{const bookingId=Number(req.params.bookingId),d=req.body||{},contractorId=Number(d.contractor_id),cost=Number(d.cost_amount),details=String(d.service_details||'').trim();const b=(await db.prepare('SELECT * FROM bookings WHERE id=?').get(bookingId)),c=(await db.prepare('SELECT * FROM contractors WHERE id=? AND active=1').get(contractorId));if(!b||b.status==='cancelled')return res.status(404).json({error:'الحجز غير موجود أو ملغي'});if(!c)return res.status(400).json({error:'اختار متعهدًا فعالًا'});if(!Number.isFinite(cost)||cost<0)return res.status(400).json({error:'التكلفة يجب أن تكون صفرًا أو أكثر'});if(!details)return res.status(400).json({error:'اكتب تفاصيل الخدمة المطلوبة للمتعهد'});const tx=db.transaction(async ()=>{(await db.prepare('UPDATE booking_work_contractors SET active=0 WHERE booking_id=? AND contractor_id=? AND active=1').run(bookingId,contractorId));(await db.prepare('INSERT INTO booking_work_contractors(booking_id,contractor_id,cost_amount,service_details,created_by) VALUES(?,?,?,?,?)').run(bookingId,contractorId,cost,details,req.user.id));(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'work_contractor_assigned','booking',bookingId,JSON.stringify({contractor_id:contractorId,cost_amount:cost,service_details:details})));});await tx();const result=await generateBookingWorkOrders(bookingId,req.user.id);res.json({ok:true,...result,message:'تم إسناد المتعهد وتحديث أوامر الشغل'})}catch(e){res.status(400).json({error:e.message})}});
app.put('/api/work-orders/:id/status',auth,permit('work_orders'),async (req,res)=>{const id=Number(req.params.id),status=String(req.body?.status||'');if(!['new','printed','delivered','in_progress','completed','cancelled'].includes(status))return res.status(400).json({error:'حالة أمر الشغل غير صحيحة'});const wo=(await db.prepare('SELECT * FROM work_orders WHERE id=?').get(id));if(!wo)return res.status(404).json({error:'أمر الشغل غير موجود'});if(wo.status==='cancelled'&&status!=='cancelled')return res.status(400).json({error:'أمر الشغل الملغي لا يعاد تفعيله؛ أنشئ إصدارًا جديدًا بعد مراجعة الحجز'});(await db.prepare('UPDATE work_orders SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(status,id));await recordWorkOrderHistory(id,wo.version,'status_changed',{old_status:wo.status,new_status:status},req.user.id);(await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'work_order_status_changed','work_order',id,JSON.stringify({old_status:wo.status,new_status:status})));res.json({ok:true,status})});
app.get('/api/work-orders/:id/history',auth,permit('work_orders'),async (req,res)=>{const rows=(await db.prepare('SELECT wh.*,u.full_name employee FROM work_order_history wh LEFT JOIN users u ON u.id=wh.user_id WHERE wh.work_order_id=? ORDER BY wh.id DESC').all(req.params.id));res.json(rows)});

