// بطاقات الدعوة الإلكترونية — رمز فريد لكل بطاقة، وحد أقصى للأفراد، وانتهاء عند نهاية الفرح.
async function invitationBooking(id){
 const b=(await db.prepare(`SELECT b.id,b.booking_no,b.event_date,b.start_time,b.end_time,b.guest_count,b.status,b.booking_stage,b.event_type,
 c.full_name customer_name,c.bride_name,h.name hall_name
 FROM bookings b LEFT JOIN customers c ON c.id=b.customer_id
 JOIN halls h ON h.id=b.hall_id WHERE b.id=?`).get(Number(id)));
 if(!b)return null;
 b.event_type_ar=({wedding:'زفاف',engagement:'خطوبة',katb_ketab:'كتب كتاب',birthday:'عيد ميلاد',other:'مناسبة سعيدة'})[b.event_type]||b.event_type||'مناسبة سعيدة';
 return b;
}
function invitationExpiry(b){
 const end=String(b.end_time||'23:59');
 let day=String(b.event_date||'');
 if(!/^\d{4}-\d{2}-\d{2}$/.test(day)) throw Error('تاريخ الحجز غير صحيح');
 // If the event ends after midnight, expiry is on the following day.
 if(String(b.start_time||'00:00')>end){
  const d=new Date(day+'T12:00:00');d.setDate(d.getDate()+1);day=d.toISOString().slice(0,10);
 }
 return `${day}T${end}:00`;
}
app.get('/api/invitations/bookings',auth,permit('invitations'),async (req,res)=>{
 const q=String(req.query.q||'').trim();
 let sql=`SELECT b.id,b.booking_no,b.event_date,b.start_time,b.end_time,b.guest_count,b.status,b.booking_stage,
 c.full_name customer_name,c.bride_name,h.name hall_name,
 (SELECT COUNT(*) FROM invitation_cards ic WHERE ic.booking_id=b.id AND ic.status='active') invitation_count,
 (SELECT COALESCE(SUM(ic.guest_limit),0) FROM invitation_cards ic WHERE ic.booking_id=b.id AND ic.status='active') invited_guests,
 (SELECT COALESCE(SUM(ic.guests_checked_in),0) FROM invitation_cards ic WHERE ic.booking_id=b.id AND ic.status='active') checked_in
 FROM bookings b LEFT JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id
 WHERE LOWER(COALESCE(b.status,'')) NOT IN ('cancelled','ملغي','مرفوض') AND
 (b.booking_stage='confirmed' OR LOWER(COALESCE(b.status,'')) IN ('confirmed','مؤكد','تم التأكيد'))`;
 const args=[];
 if(q){sql+=` AND (b.booking_no LIKE ? OR c.full_name LIKE ? OR COALESCE(c.bride_name,'') LIKE ? OR h.name LIKE ?)`;args.push(...Array(4).fill('%'+q+'%'))}
 sql+=' ORDER BY b.event_date DESC,b.start_time DESC LIMIT 300';
 try { res.json((await db.prepare(sql).all(...args))); }
 catch(e) { console.error('Invitation booking search failed:',e); res.status(500).json({error:'تعذر البحث عن الحجوزات. تأكد من تحديث قاعدة البيانات ثم أعد المحاولة.'}); }
});
app.get('/api/invitations/booking/:bookingId',auth,permit('invitations'),async(req,res)=>{
 const b=await invitationBooking(req.params.bookingId);if(!b)return res.status(404).json({error:'الحجز غير موجود'});
 const rows=(await db.prepare(`SELECT * FROM invitation_cards WHERE booking_id=? ORDER BY id DESC`).all(b.id));
 const cards=await Promise.all(rows.map(async c=>({...c,qr_data_url:await QRCode.toDataURL(c.token,{errorCorrectionLevel:'H',margin:2,width:240,color:{dark:'#111827',light:'#FFFFFF'}})})));
 res.json({booking:b,expiry:invitationExpiry(b),cards});
});
app.post('/api/invitations/booking/:bookingId/create',auth,permit('invitations'),async(req,res)=>{
 try{
  const b=await invitationBooking(req.params.bookingId);if(!b)return res.status(404).json({error:'الحجز غير موجود'});
  if(b.status==='cancelled'||b.booking_stage!=='confirmed')return res.status(400).json({error:'لا يمكن إصدار الدعوات إلا لحجز مؤكد وغير ملغى'});
  const d=req.body||{},template=String(d.template_id||'midnight'),count=1,guests=Number(d.guest_limit);
  const templates=['custom1','custom2','custom3','custom4'];
  if(!templates.includes(template))return res.status(400).json({error:'اختار تصميمًا صحيحًا'});
  // سياسة النظام: إصدار بطاقة دعوة واحدة فقط لكل حجز.
  
  if(!Number.isInteger(guests)||guests<1||guests>100)return res.status(400).json({error:'عدد الأفراد في كل بطاقة يجب أن يكون من 1 إلى 100'});
  if(count*guests>Number(b.guest_count||0))return res.status(400).json({error:`إجمالي سعة الدعوات (${count*guests}) أكبر من عدد الأفراد في الحجز (${Number(b.guest_count||0)}). قلل عدد البطاقات أو عدد الأفراد بكل بطاقة.`});
  const usedActive=(await db.prepare("SELECT COUNT(*) n FROM invitation_cards WHERE booking_id=? AND status='active' AND guests_checked_in>0").get(b.id)).n;
  if(usedActive>0)return res.status(409).json({error:'لا يمكن إصدار دفعة جديدة بعد تسجيل دخول أفراد على دعوات فعالة؛ ألغِ/راجع الدفعة مع المدير أولًا لتجنب تكرار احتساب الحضور.'});
  const expiry=invitationExpiry(b),expiryDate=new Date(expiry);
  if(!Number.isFinite(expiryDate.getTime()))return res.status(400).json({error:'تعذر تحديد نهاية المناسبة'});
  // Reissuing a batch revokes unused old cards but retains their check-in history.
  const tx=db.transaction(async ()=>{
   (await db.prepare("UPDATE invitation_cards SET status='revoked',updated_at=CURRENT_TIMESTAMP WHERE booking_id=? AND status='active'").run(b.id));
   const insert=db.prepare('INSERT INTO invitation_cards(booking_id,token,template_id,guest_limit,expires_at,created_by) VALUES(?,?,?,?,?,?)');
   const ids=[];
   for(let i=0;i<count;i++){
    const token=require('crypto').randomBytes(24).toString('base64url');
    const info=await insert.run(b.id,token,template,guests,expiry,req.user.id);ids.push(Number(info.lastInsertRowid));
   }
   (await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'invitation_cards_created','booking',b.id,JSON.stringify({count,guests,template,expiry})));
   return ids;
  });
  const ids=await tx();
  const cards=await Promise.all(ids.map(async id=>{const c=(await db.prepare('SELECT * FROM invitation_cards WHERE id=?').get(id));return {...c,qr_data_url:await QRCode.toDataURL(c.token,{errorCorrectionLevel:'H',margin:2,width:240,color:{dark:'#111827',light:'#FFFFFF'}})}}));
  res.json({ok:true,booking:b,cards,expiry,message:`تم إنشاء ${cards.length} بطاقة دعوة`});
 }catch(e){res.status(400).json({error:e.message||'تعذر إنشاء بطاقات الدعوة'})}
});
app.post('/api/invitations/:id/revoke',auth,permit('invitations'),async (req,res)=>{
 const id=Number(req.params.id),card=(await db.prepare('SELECT * FROM invitation_cards WHERE id=?').get(id));
 if(!card)return res.status(404).json({error:'بطاقة الدعوة غير موجودة'});
 if(card.guests_checked_in>0)return res.status(409).json({error:'لا يمكن إلغاء بطاقة تم تسجيل دخول أفراد بها؛ تواصل مع المدير لتصحيح سجل الدخول'});
 (await db.prepare("UPDATE invitation_cards SET status='revoked',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(id));
 (await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'invitation_card_revoked','invitation_card',id,JSON.stringify({booking_id:card.booking_id})));
 res.json({ok:true});
});
app.post('/api/invitations/scan',auth,permit('invitations'),async (req,res)=>{
 const token=String(req.body?.token||'').trim(),count=Number(req.body?.guest_count||1);
 if(!token)return res.status(400).json({error:'امسح الرمز أو أدخل رمز الدعوة'});
 if(!Number.isInteger(count)||count<1||count>100)return res.status(400).json({error:'عدد الأفراد المطلوب تسجيل دخولهم غير صحيح'});
 const card=(await db.prepare(`SELECT ic.*,b.booking_no,b.event_date,b.start_time,b.end_time,b.status booking_status,b.booking_stage,
 c.full_name customer_name,c.bride_name,h.name hall_name
 FROM invitation_cards ic JOIN bookings b ON b.id=ic.booking_id LEFT JOIN customers c ON c.id=b.customer_id JOIN halls h ON h.id=b.hall_id
 WHERE ic.token=?`).get(token));
 if(!card)return res.status(404).json({ok:false,status:'invalid',error:'رمز الدعوة غير صحيح'});
 if(card.status!=='active')return res.status(409).json({ok:false,status:'revoked',error:'هذه الدعوة ملغاة'});
 if(card.booking_status==='cancelled'||card.booking_stage!=='confirmed')return res.status(409).json({ok:false,status:'invalid',error:'الحجز غير فعال أو غير مؤكد'});
 const expiry=invitationExpiry(card),now=new Date();
 if(now.getTime()>new Date(expiry).getTime())return res.status(410).json({ok:false,status:'expired',error:'انتهت صلاحية الدعوة بانتهاء الفرح'});
 const eventStart=new Date(`${card.event_date}T${card.start_time}:00`);
 if(now.getTime()<eventStart.getTime())return res.status(403).json({ok:false,status:'not_started',error:'لم يبدأ موعد الفرح بعد؛ الدعوة غير صالحة للدخول الآن'});
 const remaining=Number(card.guest_limit)-Number(card.guests_checked_in);
 if(count>remaining)return res.status(409).json({ok:false,status:'capacity',error:`العدد المتبقي لهذه الدعوة ${Math.max(0,remaining)} فرد`});
 const tx=db.transaction(async ()=>{
  const fresh=(await db.prepare("SELECT * FROM invitation_cards WHERE id=?").get(card.id));
  if(!fresh||fresh.status!=='active')throw Error('الدعوة غير فعالة');
  const left=Number(fresh.guest_limit)-Number(fresh.guests_checked_in);
  if(count>left)throw Error(`العدد المتبقي لهذه الدعوة ${Math.max(0,left)} فرد`);
  (await db.prepare('UPDATE invitation_cards SET guests_checked_in=guests_checked_in+?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(count,card.id));
  (await db.prepare("INSERT INTO invitation_checkins(invitation_id,booking_id,guest_count,result,employee_id) VALUES(?,?,?,'accepted',?)").run(card.id,card.booking_id,count,req.user.id));
  (await db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES(?,?,?,?,?)').run(req.user.id,'invitation_checkin_accepted','invitation_card',card.id,JSON.stringify({guest_count:count,booking_no:card.booking_no})));
  return (await db.prepare('SELECT * FROM invitation_cards WHERE id=?').get(card.id));
 });
 try{
  const fresh=await tx();
  res.json({ok:true,status:fresh.guests_checked_in>=fresh.guest_limit?'full':'accepted',message:fresh.guests_checked_in>=fresh.guest_limit?'تم تسجيل الدخول واكتمل العدد المسموح':'الدعوة صالحة — تم تسجيل الدخول بنجاح',booking_no:card.booking_no,customer_name:card.customer_name,bride_name:card.bride_name,hall_name:card.hall_name,event_date:card.event_date,guest_limit:fresh.guest_limit,guests_checked_in:fresh.guests_checked_in,remaining:fresh.guest_limit-fresh.guests_checked_in,expires_at:fresh.expires_at});
 }catch(e){res.status(409).json({ok:false,status:'capacity',error:e.message})}
});
app.get('/api/invitations/:id/checkins',auth,permit('invitations'),async (req,res)=>{
 const rows=(await db.prepare('SELECT ci.*,u.full_name employee FROM invitation_checkins ci LEFT JOIN users u ON u.id=ci.employee_id WHERE ci.invitation_id=? ORDER BY ci.id DESC').all(Number(req.params.id)));
 res.json(rows);
});

